#!/usr/bin/env bash
set -euo pipefail

CONF_DIR="/etc/sddm.conf.d"
CONF_FILE="${CONF_DIR}/70-wlboard.conf"

if [[ "${1:-}" == "--remove" ]]; then
    if [[ -f "${CONF_FILE}" ]]; then
        sudo rm -f "${CONF_FILE}"
        echo "Removed ${CONF_FILE}."
    else
        echo "${CONF_FILE} does not exist."
    fi
    exit 0
fi

echo "Configuring SDDM Wayland login screen to use wlboard (/usr/share/wlboard/scripts/wlboard-sddm-kwin)..."
sudo install -d -m 755 "${CONF_DIR}"
sudo tee "${CONF_FILE}" >/dev/null <<'EOF'
# Generated by /usr/share/wlboard/scripts/setup-sddm.sh
# Enables wlboard as the Wayland virtual keyboard on the SDDM login screen
# (including non-touchscreen / VM systems via KWIN_IM_SHOW_ALWAYS=1).
# Note: Do not set InputMethod= under [General] when using kwin_wayland --inputmethod.

[General]
DisplayServer=wayland

[Wayland]
CompositorCommand=/usr/share/wlboard/scripts/wlboard-sddm-kwin
EOF

echo "Installed ${CONF_FILE}."
echo "Reboot or restart SDDM to test wlboard on the Wayland login screen."
echo "To revert at any time, run: $0 --remove"
